17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.util.List;
20	
21	/**
22	 * Thrown when an owner payload is missing or blank in one or more required fields.
23	 * The carried list holds the name of each offending field, which
24	 * {@link ExceptionControllerAdvice} reports back to the client as a 400 response.
25	 */
26	public class MissingOwnerFieldsException extends RuntimeException {
27	
28	    private final List<String> fields;
29	
30	    public MissingOwnerFieldsException(List<String> fields) {
31	        super("Missing or blank owner fields: " + fields);
32	        this.fields = List.copyOf(fields);
33	    }
34	
35	    public List<String> getFields() {
36	        return this.fields;
37	    }
38	
39	}
